// Loop through each row in the sheet
const rows = $input.all();
const results = [];

for (const item of rows) {
  const row = item.json;

  // Customize these fields based on your sheet structure
  const recipientEmail = row.email || row.Email;
  const recipientName = row.name || row.Name;

  // Skip rows without email addresses
  if (!recipientEmail) continue;

  // Build personalized subject and body
  const personalizedSubject = `Hi ${recipientName}, your custom subject here`;
  const personalizedBody = `Dear ${recipientName},\n\nYour personalized message goes here. You can reference other fields from your sheet like company: ${row.company || 'N/A'}.\n\nBest regards,\nYour Team`;

  results.push({
    json: {
      toEmail: recipientEmail,
      subject: personalizedSubject,
      body: personalizedBody
    }
  });
}

return results;
